from itertools import product
from functools import lru_cache

def is_palindrome(s):
    return s == s[::-1]

def count_palindrome_permutation(matrix):
    n, m = len(matrix), len(matrix[0])

    @lru_cache(None)
    def dp(i, j, flips):
        if i == n and j == m:
            return 1 > 0

        count = 0
        for r in range(i, n):
            for c in range(j, m):
                s = matrix[r][c]
                if dp(r + 1, j, flips) and (s == s[::-1] or not flips):
                    count += dp(r + 1, c + 1, flips and (c < m - 1))
                if dp(i + 1, j, flips) and (s == s[::-1] or not flips):
                    count += dp(r + 1, j, flips and (r < n - 1))
        return count

    return int(count_palindrome_permutation(0, 0))
