def min_lowercase_uppercase_changes(n, k, l, handle):
    """
    Calculate the minimum number of lowercase and uppercase changes needed
    to equalize the number of lowercase and uppercase letters in the handle,
    given at most k changes and a segment length l.
    """
    count_lower = 0
    count_upper = 0
    for i in range(n):
