                    if input_string[j] in operators:
                        temp = dfs(j + 1)
                        if result == 0:
                            result += temp
                        elif result == temp:
                            result = temp * temp + result if char == '/' else result + temp
                        elif result == temp + result:
                            continue
                        elif result != temp:
                            return 0
        return result

