from collections import defaultdict, deque

def find(parent, i):
    if parent[i] == i:
        return i
    return find(parent, parent[i])

def union(parent, ranks, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if ranks[rootX] < ranks[rootY]:
        parent[rootX] = rootY
    elif ranks[rootX] > ranks[rootY]:
        parent[rootY] = rootX
    else:
        parent[rootY] = rootX
        ranks[rootX] += 1

def bridges(graph):
    n = len(graph)
    timer = 0
    parent = {}
    ranks = []

    def dfs(node, parent=None):
        nonlocal timer
        timer += 1
        low[node] = timer
        stack = [(node, timer)]
        visited[node] = True
        for neighbor in graph[node]:
            if neighbor == parent:
                continue
            if not visited[neighbor]:
                if neighbor not in visited:
                    stack.append((neighbor, timer))
                low[neighbor] = low[node] + 1
                dfs(neighbor, node)
            elif not visited:
                dfs(neighbor, node)
        return low[node]

    for vertex in range(n):
        visited[vertex] = False
        parent[vertex] = -1
        ranks.append(0)
    timer = 0

    low = [0] * n
    dfs(0)
    parent = defaultdict(lambda: -1)

    for edge in graph:
        union(parent, ranks, edge[0], edge[1])

    for i in range(n):
        parent[i] = find(parent, i)

    for i in range(n):
        if i == find(parent, i):
            continue
        prev = find(parent, parent[i])
        while prev != i:
            prev = find(parent, prev)
            parent[prev] = i
        # When above loop finishes, all nodes in tree rooted at `i` are in `i`
        for edge in graph[i]:
            if low[find(parent, edge[0])] < low[find(parent, edge[0])]:
                cut = min(low[edge[0]], low[i])
                if cut > low[find(parent, edge[1])]:
                    if find(parent, edge[0]) != find(parent, edge[1]):
                        yield (i, min(low[edge[0]], low[i]), max(low[edge[0]] + 1, low[edge[1]] - 1), low[edge[1]] - 1)
