from collections import Counter, defaultdict

def is_palindrome(s):
    return s == s[::-1]

def count_palindromes(matrix, n, m):
    # Initialize counts for each character combination
    counts = Counter()
    for i in range(n):
        for j in range(m):
            old_counts = counts.copy()
            new_counts = Counter()

            # Update the counts for each character combination
            for x in list(old_counts):
                new_counts[x + matrix[i][j]] += old_counts[x]
                new_counts[2 * (matrix[i][j]) + matrix[i][j]] += old_counts[x]
                new_counts[2 * matrix[i][j] + matrix[i][j]] += old_counts[x]
            counts = new_counts

    return len(counts)

def is_beautiful(matrix, s):
    n, m = len(matrix), len(matrix[0])
    if len(matrix) < len(s) or len(matrix[0]) < len(s):
        return False

    s_counts = Counter()
    pal_s = set()
    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            e = matrix[i][j]
            # Check if a character or pair is replaced, check all pairs
            if s[i] == matrix[i][j] or s[i] != matrix[i][j] and s[j] != matrix[i][j]:
                s_counts[s[j]] += 1
                if s_counts == Counter():
                    pal_s.add(s)
                break
    if len(s) % 2 == 0:
        return (pal_s & {s}) != set()
    return (pal_s & {s}) != set() and any(not (s_counts & Counter(s[j:] for j in range(1, len(s), 2))).most_common(1)[0][1] and not (s_counts & Counter(s[j:j+len(s)//2:2])).most_common(1)[0][1] and any((s_counts & Counter(s[j:j+len(s)//2+1:2])).most_common(1)[0][1] and not (s_counts & Counter(s[j:len(s):2])).most_common(1)[0][1])

def count_beautiful_submatrices(matrix, n, m):
    count1 = 0
    for i in range(n - m + 1):
        for j in range(m - 1):
            if i == 0:
                if is_beautiful(matrix, matrix[i][j:j+m]):
                    count1 += 1
            else:
                for k in range(i, n-m+1):
                    s = ''.join(matrix[k + y][j:j+m] for y in range(m - 1))
                    if is_beautiful(matrix, s):
                        count1 += 1
                break
    return count1

