import sys

def find_parent(parent, x):
    if parent[x] == x:
        return x
    return find_parent(parent, parent[x])

def union(parent, rank, x, y):
    xroot = find_parent(parent, x)
    yroot = find_parent(parent, y)

    if xroot == yroot or rank[xroot] < rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[xroot] = yroot
        if rank[xroot] == rank[yroot]:
            rank[yroot] += 1

def is_tree_connected(n, edges):
    parent = list(range(n))
    rank = [0] * n

    for i in range(1, n):
        union(parent, rank, i, i + 1)

    for u, v in edges:
        if find_parent(parent, u) == find_parent(parent, v):
            return False
    return True

