def count_palindromes(s):
    return sum(is_palindrome(sub) for sub in set(combinations(s, len(s) // 2)))

def dfs(sub, L, choices):
    if 2 * len(sub) == L:
        return 1
    count = 0
    for choice in choices:
        left = sub[:sub.index(choice)]
        right = sub[sub.index(choice) + 1 :]
        count += dfs(left, L, set(choices) - set(left)) * dfs(right, L, choices - set(left) - set(right))
    return count

def count_beautiful_submatrixes(n, m, rows):
    palindromes = 0
    for i in range(n):
        for j in range(m):
            palindromes += dfs(set(rows[i][-j-1:]), 2 * j + 1, {rows[i][-j-1]}) * count_palindromes(rows[i][-j:])
    return palindromes

