import math

def is_prime(num):
    if num <= 1:
        return False
    if num == 2 or num == 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def min_level_for_deck(cards, power_required):
    cards.sort(key=lambda x: x[0], reverse=True)
    cards.append((math.inf, 0, math.inf))
    min_prime_sum = -math.inf
    level = 1

    for i, card in enumerate(cards[:-1]):
        card_power, card_magic, card_level = card
        next_card = cards[i + 1]
        next_card_power, next_card_magic, next_card_level = next_card

        while is_prime(card_magic + next_card_magic):
            level += 1
            next_card = cards[i + (level - 2)]

        if card_level <= level and card_magic + next_card_magic <= power_required:
            if card_magic + next_card_magic > min_prime_sum:
                min_prime_sum = card_magic + next_card_magic
            level = next_card_level

        if i > 0 and card_magic + card_power <= power_required:
            level += 1

    if min_prime_sum == -math.inf:
        return -1
    return level

