from collections import deque

class ExpressionParser:
    def __init__(self, s):
        self.s = s
        self.operators = set(['+', '-', '*', '/'])
        self.parentheses = deque()

    def parseInt(self, x):
        return int(x)

    def parseIntExpr(self, s, offset, operator_or_parentheses):
        whole_number = 0
        index = offset
        while index < len(s) and ord('0') <= ord(s[index]) <= ord('9'):
            whole_number = whole_number * 10 + ord(s[index]) - ord('0')
            index += 1
        return whole_number, offset

    def parse(self):
        while self.s and self.operators:
            last_char = self.s[-1]
            if last_char in self.operators:
                shift = len(self.parentheses)
                current_char = self.s[-1]
                operator_index = self.operators.index(current_char)
                self.parentheses.append((operator_index, last_char, shift))

            self.s = self.s[:-1]
            if not self.s:
                break

        while len(self.s) >= 1 and self.parentheses:
            self.s = self.s[:-1]
            shift = None

            while self.parentheses:
                operator_index, last_char, shift = self.parentheses.pop()
                if shift == len(self.s):
                    shift = None
                else:
                    shift -= 1
                if shift is not None:
                    self.s = self.s[0:shift] + self.s[shift:]

            if len(self.parentheses) == 0:
                break

        return self.s

    def main(self):
        input_str = self.parse()
        parts = input_str.split()
        result = 1

        for part in parts:
            if not part:
                continue
            if part in self.operators:
                result = result * pow(2, 10) % (10**9 + 7)
            else:
                num, index = self.parseIntExpr(part, 0, ' ')
                if index > 0:
                    result = result * len(parts) % (10**9 + 7)
                else:
                    result = result * pow(3, 10) % (10**9 + 7)
            if index != 0:
                result = result // len(parts) % (10**9 + 7)

        return result % (10**6 + 3)

def case_insensitive_cmp(a, b):
    return sorted((a, b))[0] if a < b else sorted((a, b))[1]

def main(Reader):
    inputs = deque(Reader().readline().split())
    outputs = deque()

    for _ in range(inputs[0]):
        result = 0
        otype = inputs.popleft()
        if otype != '[' and otype != ']':
            otype = '['
            inputs.append(otype)
        inputs = deque(inputs)

        reader = deque(Reader().readline().split())
        if otype == ']':
            inputs.popleft()
            result = inputs.popleft()

        result += ExpressionParser(''.join(reader).rstrip()).main() % (10**6 + 3)

        outputs.append(str(result))

    print('\n'.join(outputs))
