import sys

MOD = 10**9 + 7

def count_occurrences(song, name):
    count = 0
    j = 0
    for i in range(len(song)):
        if j == len(name):
            break
        if song[i] == name[j]:
            count += 1
            j += 1
    return count

def process_query(query, name):
    p = 1
    for i in range(query + 1):
        p = (p * i) % MOD
    q = pow(26, MOD - 2, MOD) * count_occurrences(song[query], name) % MOD
    return (p * q) % MOD

def solve(output_file):
