from typing import List, Tuple
from itertools import product

def count_beautiful_submatrices(n: int, m: int, matrix: List[str]) -> int:
    directions = [(0, -1), (0, 1)]
    dp = [[0] * (2*m) for _ in range(n)]

    for i, j in product(range(n), range(m)):
        char = matrix[i][j]
        for d in directions:
            off = d[0] * i + d[1] * j
            if off == 0:
                dp[i % n][j] += 1
            for o in range(-dp[i % n][j], dp[i % n][j]):
                if dp[(i + off * o) % n][(j + o * (m - 1)) % (2*m)] + dp[i % n][j] - 1 - dp[(i - o * off) % n][(j + o * off) % (2*m)] == 0:
                    dp[i % n][j] += 1

    return sum(dp[n % n])

