# Function to find the MST and update the maximum weight for the selected edge
def find_mst(selected_edge):
    visited = set()
    min_span_tree = []

    # Depth-first search to find the MST
    def dfs(u, parent):
        visited.add(u)
        for v, c in graph[u].items():
            if v not in visited and c < selected_edge:
                dfs(v, u)
                min_span_tree.append((u, v, c))

    dfs(selected_edge[0], -1)

    min_cost = min([c for _, _, c in min_span_tree])

    # Check if the MST is unique
    if min_cost == min(c for _, _, c in min_span_tree):
        return True

    # Update the max_weights for edges in the MST
    for u, v, c in min_span_tree:
        if max_weights.get(u, -1) == -1 or max_weights[u] < c:
            max_weights[u] = c

        if max_weights.get(v, -1) == -1 or max_weights[v] < c:
            max_weights[v] = c

        if max_weights.get(u + v, -1) == -1 or max_weights[u + v] < c:
            max_weights[u + v] = c

    return False

# Process each edge
