def is_good_kd_sequence(sequence, k, d):
    n = len(sequence)
    for i in range(n):
        # Check if the sequence can be turned into an arithmetic progression with the given difference by adding at most k numbers
        if sum(sequence[i:i + k]) % d == 0 and sum(sequence) % d == 0:
